from content_helpers import code, output, choice, lesson, section, program

def sections():
    return [section("loops", "5. Повторение и алгоритмы", "От счётчика до обработки телеметрии без хранения всей последовательности.", [
        lesson("for", "Цикл for", "Повторяйте действие известное число раз.",
            "for (int i = 0; i < n; ++i) { ... } создаёт счётчик i, проверяет условие перед каждой итерацией и увеличивает i после тела. Для n=3 тело увидит i равным 0, 1, 2. ++i увеличивает переменную на один. Сейчас используем инкремент отдельным шагом, а не внутри сложных выражений.\n\nЕсли условие ложно сразу, тело не выполняется ни разу. Переменная, объявленная в заголовке for, доступна внутри цикла, но не после него. Чтобы накопить сумму, создайте sum=0 перед циклом и добавляйте значение внутри. Не обнуляйте sum на каждой итерации.\n\nРазделители при выводе продумывайте отдельно: можно поставить if (i > 0) перед пробелом, чтобы не было лишнего пробела в конце.",
            program('int n = 0;\nstd::cin >> n;\nint sum = 0;\nfor (int i = 1; i <= n; ++i) {\n    sum += i;\n}\nstd::cout << sum;'),
            "Цикл for — не команда «повтори ровно n раз» сама по себе: всё определяется начальным состоянием, условием и шагом. i <= n при старте с 0 даёт n+1 итераций для неотрицательного n. Проверяйте границу на n=0 и n=1.",
            "Инициализация один раз → условие → тело → шаг → снова условие. Накопитель объявляйте до цикла.", [
                code("squares", "Плитки для дорожки", 'Ввод: n (0…100). Выведите сумму квадратов чисел от 1 до n. Для n=0 выведите 0. Используйте long long для суммы: int может быть недостаточно на некоторых реализациях.', 'int n = 0;\nstd::cin >> n;\nlong long sum = 0;\nfor (int i = 1; i <= n; ++i) {\n    sum += i * i;\n}\nstd::cout << sum;', [("3", "14"), ("0", "0"), ("100", "338350")], ["Квадраты i*i не больше 10000, но их сумма больше 32767.", "На каждой итерации добавляйте i*i к long long sum."], "long long гарантированно имеет диапазон не уже 64 бит. Промежуточный квадрат в int здесь безопасен, а сумма расширена.", difficulty=2),
                output("boundary", "Сколько сигналов?", 'for (int i = 0; i <= 3; ++i) {\n    std::cout << i;\n}', "0123", ["Начальное значение 0 тоже участвует.", "Условие <= включает 3."], "Четыре итерации выводят четыре цифры без пробелов."),
                code("countdown", "Настоящий обратный отсчёт", 'Ввод: n (1…20). Выведите числа от n до 1, каждое на своей строке, затем Go! на новой строке.', 'int n = 0;\nstd::cin >> n;\nfor (int i = n; i >= 1; --i) {\n    std::cout << i << "\\n";\n}\nstd::cout << "Go!";', [("3", "3\n2\n1\nGo!"), ("1", "1\nGo!")], ["Счётчик должен уменьшаться, а не увеличиваться.", "Используйте --i после тела, а Go! печатайте уже после цикла."], "--i уменьшает i на единицу. Финальная команда выполняется один раз."),
                choice("accumulator", "Сумма исчезает", 'Почему sum=0 внутри тела перед sum+=i не накапливает сумму всех i?', ["На каждой итерации прошлый результат затирается", "В цикле нельзя складывать", "Переменная sum должна обязательно быть double"], 0, ["Обнуление — тоже присваивание.", "Для накопления нужно сохранить результат предыдущей итерации."], "Инициализация sum должна происходить один раз до цикла."),
                code("evens", "Чётные посадочные места", 'Ввод: n (1…30). Выведите первые n положительных чётных чисел в одной строке через один пробел, без пробела в конце.', 'int n = 0;\nstd::cin >> n;\nfor (int i = 1; i <= n; ++i) {\n    if (i > 1) { std::cout << " "; }\n    std::cout << 2 * i;\n}', [("4", "2 4 6 8"), ("1", "2")], ["Число с номером i равно 2*i.", "Пробел печатайте перед всеми числами, кроме первого."], "Условие i>1 отделяет форматирование от вычисления значения.", difficulty=2)
            ], ["for", "счётчик", "накопитель"]),
        lesson("while", "while и do while", "Повторяйте, пока выполняется условие.",
            "while (condition) { ... } проверяет условие перед каждой итерацией. Он удобен, когда заранее неизвестно число повторений. Внутри обязательно должно меняться состояние, от которого зависит продолжение, иначе можно получить бесконечный цикл.\n\nДля обработки цифр положительного n берите n%10 и отбрасывайте последнюю цифру через n/=10. Операция /= — сокращённое присваивание частного. Число 0 требует отдельного внимания: while(n>0) не выполнится для него. do { ... } while (condition); проверяет условие после тела и выполнит его хотя бы один раз. После while в этой конструкции нужна точка с запятой.\n\nТип long long хранит большие целые в этих задачах; начальные значения и пределы всё равно должны быть заданы.",
            program('int n = 0;\nstd::cin >> n;\nint digits = 0;\ndo {\n    ++digits;\n    n /= 10;\n} while (n > 0);\nstd::cout << digits;'),
            "Цикл сам по себе не гарантирует завершение. Для обработки неотрицательного целого через /=10 положительное значение строго уменьшается и достигает нуля. Такой аргумент показывает, почему здесь не будет бесконечного цикла. Для знаковых отрицательных чисел условие n>0 вообще не запускает тело; не расширяйте контракт без пересмотра алгоритма.",
            "while может выполнить тело ноль раз, do while — минимум один. Для числа 0 явно выберите правильную модель цифр.", [
                code("digitsum", "Контрольная сумма кода", 'Ввод: целое n (0…10000). Выведите сумму его десятичных цифр.', 'int n = 0;\nstd::cin >> n;\nint sum = 0;\nwhile (n > 0) {\n    sum += n % 10;\n    n /= 10;\n}\nstd::cout << sum;', [("407", "11"), ("0", "0"), ("10000", "1")], ["Последняя цифра — n%10.", "После добавления цифры уменьшите n через n/=10."], "Для n=0 сумма уже правильно равна начальному нулю, поэтому отдельная итерация не требуется."),
                output("once", "Хотя бы один раз", 'int n = 0;\ndo {\n    std::cout << "A";\n    ++n;\n} while (n < 0);', "A", ["Условие проверяется после тела.", "Первая итерация происходит даже при ложном продолжении."], "do while выполняет тело один раз, затем прекращается."),
                code("digitcount", "Длина числового позывного", 'Ввод: n (0…10000). Выведите число десятичных цифр. У нуля одна цифра. Используйте do while.', 'int n = 0;\nstd::cin >> n;\nint count = 0;\ndo {\n    ++count;\n    n /= 10;\n} while (n > 0);\nstd::cout << count;', [("0", "1"), ("9000", "4"), ("7", "1")], ["Нужно посчитать хотя бы одну цифру.", "Счётчик увеличивается до проверки оставшегося n."], "do while естественно обрабатывает ноль без особой ветки."),
                choice("termination", "Забытый шаг", 'Что будет с while (n > 0) { std::cout << n; }, если n=3 и n нигде не меняется?', ["Тело выполнится три раза", "Цикл сам уменьшит n", "Условие останется истинным и программа будет продолжать вывод"], 2, ["while не содержит неявного счётчика.", "Проверьте, меняет ли тело значение n."], "Неизменное истинное условие приводит к неограниченному повторению. Такой эталон не нужно запускать."),
                code("growth", "Рост колонии", 'Ввод: цель target (1…10000). Колония начинает с 1 клетки и каждый час удваивается. Выведите минимальное число часов до достижения хотя бы target клеток. Используйте long long для количества.', 'int target = 0;\nstd::cin >> target;\nlong long cells = 1;\nint hours = 0;\nwhile (cells < target) {\n    cells *= 2;\n    ++hours;\n}\nstd::cout << hours;', [("1", "0"), ("8", "3"), ("9", "4"), ("10000", "14")], ["Если цель уже равна 1, ждать не нужно.", "Повторяйте удвоение, пока cells < target."], "Условие <, а не <=, останавливает рост ровно на достигнутой цели.", difficulty=2)
            ], ["while", "do while", "цифры", "завершение"]),
        lesson("flow", "break, continue и вложенность", "Останавливайте поиск и пропускайте ненужные значения.",
            "break завершает ближайший цикл или switch. continue пропускает оставшуюся часть текущей итерации: в for после него выполняется шаг, затем условие; в while сразу проверяется условие. Неверно поставленный continue может пропустить изменение счётчика while и создать бесконечный цикл.\n\nВо вложенном цикле внутренний полностью отрабатывает для каждого значения внешнего. Для таблицы из rows строк и cols символов внешний цикл отвечает за строки, внутренний — за содержимое строки. Перенос выводите после внутреннего цикла.\n\nВ потоковой обработке заранее известного количества данных не прекращайте чтение раньше времени без причины: если следом нужны другие данные, непрочитанные значения остаются во входном потоке.",
            program('for (int row = 0; row < 2; ++row) {\n    for (int col = 0; col < 3; ++col) {\n        std::cout << "#";\n    }\n    std::cout << "\\n";\n}'),
            "break во внутреннем цикле не завершает внешний. Область действия определяется структурой программы, а не числом скобок на экране. Для сложного управления несколькими циклами полезнее переработать алгоритм или выделить функцию, чем придумывать скрытые переходы.",
            "Вложенные циклы разделяют строки и столбцы. break выходит из ближайшего цикла, continue — только из текущей итерации.", [
                code("positive", "Только полезные показания", 'Ввод: n (0…100), затем n целых показаний от −100 до 100. Выведите сумму строго положительных. Используйте continue для пропуска неположительных.', 'int n = 0;\nstd::cin >> n;\nint sum = 0;\nfor (int i = 0; i < n; ++i) {\n    int value = 0;\n    std::cin >> value;\n    if (value <= 0) { continue; }\n    sum += value;\n}\nstd::cout << sum;', [("5 3 -2 0 7 -8", "10"), ("0", "0"), ("2 -1 -2", "0")], ["Каждое показание всё равно нужно прочитать.", "После чтения пропускайте value<=0, а остальные добавляйте."], "continue не мешает шагу for и чтению следующего значения."),
                output("skip", "Пропуск и остановка", 'for (int i = 1; i <= 5; ++i) {\n    if (i == 2) { continue; }\n    if (i == 4) { break; }\n    std::cout << i;\n}', "13", ["2 пропускается, но цикл продолжается.", "При 4 break срабатывает до вывода."], "Значение 5 уже не достигается: цикл завершён."),
                code("grid", "Пиксельная панель", 'Ввод: rows и cols (1…10). Выведите rows строк из cols символов #. После каждой строки, включая последнюю, выведите перенос.', 'int rows = 0, cols = 0;\nstd::cin >> rows >> cols;\nfor (int row = 0; row < rows; ++row) {\n    for (int col = 0; col < cols; ++col) {\n        std::cout << "#";\n    }\n    std::cout << "\\n";\n}', [("2 3", "###\n###\n"), ("1 1", "#\n")], ["Один цикл управляет строками, другой — столбцами.", "Перенос разместите после внутреннего цикла, но внутри внешнего."], "В этом условии завершающий перенос явно включён в ожидаемый результат.", difficulty=2),
                choice("inner", "Какой цикл остановится?", 'break находится в теле внутреннего for, вложенного во внешний for. Что он завершает?', ["Только ближайший внутренний цикл", "Оба цикла сразу", "Всю программу"], 0, ["break имеет локальную область действия.", "После внутреннего цикла внешний продолжает свою работу."], "Чтобы завершить алгоритм целиком, одного break во внутреннем цикле недостаточно."),
                code("divisor", "Первый делитель", 'Ввод: n (2…1000). Найдите наименьший делитель n, больший 1, и выведите его. Перебирайте кандидатов и остановитесь через break после первого найденного.', 'int n = 0;\nstd::cin >> n;\nfor (int d = 2; d <= n; ++d) {\n    if (n % d == 0) {\n        std::cout << d;\n        break;\n    }\n}', [("15", "3"), ("17", "17"), ("2", "2"), ("1000", "2")], ["Проверка делимости — остаток, равный нулю.", "Идите от 2 вверх: первый успех и будет минимальным."], "Для простого n первым подходящим делителем окажется само n. Граница <=n необходима.", difficulty=2)
            ], ["break", "continue", "вложенные циклы"]),
        lesson("telemetry", "Контрольная: телеметрия", "Обработайте последовательность с памятью о нужном прошлом.",
            "Не любую последовательность нужно хранить целиком. Для суммы достаточно накопителя; для максимума — текущего лучшего значения; для числа подъёмов — предыдущего измерения. Это потоковые алгоритмы: новое значение прочитали, обновили состояние, перешли дальше.\n\nМаксимум непустой последовательности удобно инициализировать первым значением, а не нулём: если все числа отрицательные, ноль не является их максимумом. Сравнивайте соседние значения только со второго измерения. Контракт n≥1 позволяет безопасно прочитать первый элемент отдельно.\n\nВ итоговой задаче используем long long для суммы и вещественное деление при вычислении среднего.",
            program('int n = 0, best = 0;\nstd::cin >> n >> best;\nfor (int i = 1; i < n; ++i) {\n    int value = 0;\n    std::cin >> value;\n    if (value > best) { best = value; }\n}\nstd::cout << best;'),
            "Инвариант алгоритма — утверждение, сохраняющееся после каждой итерации. Для максимума best равен наибольшему из уже прочитанных значений. Инициализация первым элементом делает это истинным до цикла; сравнение и обновление сохраняют свойство. Это объяснение сильнее, чем один удачный пример.",
            "Храните только нужное состояние. Для максимума используйте первый элемент, а для сравнений соседей — предыдущий.", [
                code("max", "Самый тёплый сектор", 'Ввод: n (1…100), затем n целых температур от −100 до 100. Выведите максимум.', 'int n = 0, best = 0;\nstd::cin >> n >> best;\nfor (int i = 1; i < n; ++i) {\n    int value = 0;\n    std::cin >> value;\n    if (value > best) { best = value; }\n}\nstd::cout << best;', [("4 -8 -3 -12 -5", "-3"), ("1 -100", "-100"), ("3 2 9 9", "9")], ["Ноль не подходит как начальный максимум для всех отрицательных чисел.", "Прочитайте первый элемент в best, а остальные сравнивайте с ним."], "Для n=1 тело цикла не выполняется, и первый элемент остаётся максимумом.", difficulty=2),
                output("state", "Состояние накопителя", 'int sum = 0;\nfor (int i = 1; i <= 4; ++i) {\n    if (i % 2 == 0) { sum += i; }\n}\nstd::cout << sum;', "6", ["Добавляются только чётные i.", "В диапазоне 1…4 это 2 и 4."], "Сумма остаётся между итерациями, потому что объявлена до цикла."),
                code("rises", "Сколько подъёмов?", 'Ввод: n (1…100), затем n показаний от −100 до 100. Подъём — значение строго больше предыдущего. Выведите число подъёмов.', 'int n = 0, previous = 0;\nstd::cin >> n >> previous;\nint rises = 0;\nfor (int i = 1; i < n; ++i) {\n    int current = 0;\n    std::cin >> current;\n    if (current > previous) { ++rises; }\n    previous = current;\n}\nstd::cout << rises;', [("5 2 4 4 1 3", "2"), ("1 7", "0"), ("3 3 2 1", "0")], ["Сравнивайте с предыдущим, не с максимумом.", "После сравнения обязательно сохраните current в previous."], "Равные соседние измерения подъёмом не считаются. У единственного измерения нет предыдущего.", difficulty=2),
                choice("bestinit", "Максимум холодной ночи", 'Почему best=0 перед обработкой температур может дать неверный максимум?', ["Все значения могут быть отрицательными", "Максимум всегда должен быть double", "Циклы не работают с отрицательными числами"], 0, ["Попробуйте данные −8, −3, −12.", "Начальное best не должно представлять несуществующий элемент."], "Инициализация первым элементом связывает best с реальными данными."),
                code("summary", "Сводка экспедиции", 'Ввод: n (1…100), затем n целых показаний от −100 до 100. Выведите максимум и среднее с двумя знаками после точки через пробел.', 'int n = 0, best = 0;\nstd::cin >> n >> best;\nlong long sum = best;\nfor (int i = 1; i < n; ++i) {\n    int value = 0;\n    std::cin >> value;\n    sum += value;\n    if (value > best) { best = value; }\n}\nstd::cout << best << " " << std::fixed << std::setprecision(2) << static_cast<double>(sum) / n;', [("3 -4 2 8", "8 2.00"), ("1 -7", "-7 -7.00"), ("2 1 2", "2 1.50")], ["Первое значение участвует и в сумме, и в максимуме.", "Оставшиеся n-1 значений обработайте в одном цикле; перед делением преобразуйте сумму."], "Один проход поддерживает два независимых состояния. Для среднего n гарантированно не равно нулю.", headers="iostream iomanip", difficulty=3)
            ], ["контрольная", "потоковые алгоритмы", "инвариант"])
    ])]
